-- LOCAL throwaway PG16 only. Live table shapes for the league_* tables (read-only catalog SELECT, 2026-11-03).
-- Not a migration. Never run on the live project.
create schema if not exists auth;
create table if not exists auth.users (id uuid primary key, email text);
create or replace function auth.uid() returns uuid language sql stable as $f$ select coalesce(nullif(current_setting('qa.uid', true), ''), nullif(current_setting('request.jwt.claims', true), '')::jsonb->>'sub')::uuid $f$;
create schema if not exists extensions;
create extension if not exists pgcrypto with schema extensions;
create table if not exists public.profiles (id uuid primary key, display_name text, role text default 'user', hcp_index numeric);
create table if not exists public.games (code text primary key, data jsonb, updated_at timestamptz, owner_anonymized boolean, type text, owner_uid uuid, participants uuid[]);
create table public.leagues (id uuid not null default gen_random_uuid() primary key, name text not null, mode text not null default 'weekly'::text, home_course_id text, commissioner_id uuid not null, logo jsonb, created_at timestamp with time zone not null default now(), archived_at timestamp with time zone);
create table public.league_absences (id uuid not null default gen_random_uuid() primary key, season_id uuid not null, matchup_id uuid not null, member_id uuid not null, week_number integer not null, declared_at timestamp with time zone not null default now(), declared_by uuid, notice_hours numeric, is_no_show boolean not null default false, resolution text not null default 'pending'::text, resolved_at timestamp with time zone, resolved_by uuid, sub_member_id uuid, claim_status text not null default 'closed'::text, claimed_by uuid, claimed_at timestamp with time zone, note text, created_at timestamp with time zone not null default now(), current_member_id uuid);
create unique index league_absences_matchup_member_uq on public.league_absences (matchup_id, member_id);
create table public.league_audit (id uuid not null default gen_random_uuid() primary key, season_id uuid not null, actor_id uuid, action text not null, target_type text, target_id uuid, before jsonb, after jsonb, at timestamp with time zone not null default now());
create table public.league_cards (id uuid not null default gen_random_uuid() primary key, matchup_id uuid not null, member_id uuid, entrant_id uuid not null, slot integer not null, source text not null, game_code text, played_by_member_id uuid, gross integer[], net integer[], handicap_used numeric, witness_count integer, posted_by uuid, posted_at timestamp with time zone not null default now(), approved_by uuid, approved_at timestamp with time zone, auto_approved boolean not null default false, disputed_by uuid, dispute_note text, created_at timestamp with time zone not null default now(), putts integer[], gir boolean[], fairways boolean[], course_id text, course_name text, course_pars integer[], net_to_par integer);
create table public.league_flight_history (season_id uuid not null, entrant_kind text not null, entrant_id uuid not null, segment text not null, flight integer not null, set_at timestamp with time zone not null default now(), primary key (season_id, entrant_kind, entrant_id, segment));
create table public.league_handicaps (id uuid not null default gen_random_uuid() primary key, season_id uuid not null, member_id uuid not null, week_number integer not null, suggested numeric, suggested_basis jsonb not null default '{}'::jsonb, effective numeric not null, source text not null, set_by uuid, set_at timestamp with time zone not null default now(), note text, unique (season_id, member_id, week_number));
create table public.league_matchups (id uuid not null default gen_random_uuid() primary key, week_id uuid not null, entrant_kind text not null, a_entrant_id uuid not null, b_entrant_id uuid, kind text not null, status text not null default 'scheduled'::text, a_points numeric, b_points numeric, points_possible numeric, presence_mode text, result_json jsonb not null default '{}'::jsonb, finalized_at timestamp with time zone, created_at timestamp with time zone not null default now(), game_code text);
create unique index league_matchups_week_entrant_uq on public.league_matchups (week_id, a_entrant_id);
create table public.league_members (id uuid not null default gen_random_uuid() primary key, season_id uuid not null, user_id uuid, display_name text not null, display_name_norm text, team_id uuid, role text not null default 'player'::text, is_sub_pool boolean not null default false, status text not null default 'active'::text, flight integer, invite_email text, invite_token text, invite_sent_at timestamp with time zone, claimed_by uuid, claimed_at timestamp with time zone, joined_week integer, activated_week integer, left_week integer, pay_handle text, created_at timestamp with time zone not null default now(), invite_phone text, tee_id text);
create table public.league_money (id uuid not null default gen_random_uuid() primary key, season_id uuid not null, week_id uuid, member_id uuid, team_id uuid, party text not null, kind text not null, amount numeric(10,2) not null, status text not null default 'owed'::text, note text, created_at timestamp with time zone not null default now(), settled_at timestamp with time zone);
create table public.league_notif_log (week_id uuid not null, user_id uuid not null, kind text not null, sent_on date not null default CURRENT_DATE, sent_at timestamp with time zone not null default now(), primary key (week_id, user_id, kind, sent_on));
create table public.league_pool_optouts (id uuid not null default gen_random_uuid() primary key, season_id uuid not null, week_id uuid not null, kind text not null, member_id uuid not null, set_by uuid, set_at timestamp with time zone not null default now(), unique (week_id, kind, member_id));
create table public.league_pool_winners (id uuid not null default gen_random_uuid() primary key, season_id uuid not null, week_id uuid not null, kind text not null, hole integer, member_id uuid not null, set_by uuid, set_at timestamp with time zone not null default now());
create unique index league_pool_winners_uq on public.league_pool_winners (week_id, kind, coalesce(hole, 0));
create table public.league_seasons (id uuid not null default gen_random_uuid() primary key, league_id uuid not null, name text not null, status text not null default 'planning'::text check (status = any (array['planning','active','playoffs','complete','archived'])), settings jsonb not null default '{}'::jsonb, settings_locked jsonb not null default '{}'::jsonb, schedule_mode text not null, start_date date, end_date date, round_target integer, timezone text not null, join_code text, join_code_expires_at timestamp with time zone, join_code_max_uses integer, join_code_uses integer not null default 0, join_code_rotated_at timestamp with time zone, public_standings boolean not null default false, public_token text, created_by uuid not null, created_at timestamp with time zone not null default now(), archived_at timestamp with time zone, locked_at timestamp with time zone);
create table public.league_standings (season_id uuid not null, entrant_kind text not null, entrant_id uuid not null, segment text not null check (segment = any (array['h1','h2','full','playoff'])), flight integer, points numeric not null default 0, points_possible numeric not null default 0, weeks_played integer not null default 0, weeks_absent integer not null default 0, wins integer not null default 0, losses integer not null default 0, ties integer not null default 0, low_gross integer, low_net integer, skins_won numeric not null default 0, rank integer, tiebreak_json jsonb not null default '{}'::jsonb, computed_through_week integer, finalize_id uuid, computed_at timestamp with time zone not null default now(), to_par integer, dq boolean not null default false, dq_week integer, primary key (season_id, entrant_kind, entrant_id, segment));
create table public.league_sub_invites (id uuid not null default gen_random_uuid() primary key, absence_id uuid not null, season_id uuid not null, invitee_member_id uuid not null, invited_by uuid, status text not null default 'pending'::text, note text, sent_at timestamp with time zone not null default now(), responded_at timestamp with time zone);
create table public.league_teams (id uuid not null default gen_random_uuid() primary key, season_id uuid not null, name text not null, color text, captain_member_id uuid, flight integer, active_from_week integer not null default 1, active_to_week integer, created_at timestamp with time zone not null default now());
create table public.league_weeks (id uuid not null default gen_random_uuid() primary key, season_id uuid not null, week_number integer not null, date date, tee_time time without time zone, course_id text, nine text not null default 'full18'::text, tee_id text, format text not null, format_config jsonb not null default '{}'::jsonb, settings_snapshot jsonb not null default '{}'::jsonb, course_snapshot jsonb not null default '{}'::jsonb, presence_mode text, solo_settlement text, points_possible numeric, status text not null default 'scheduled'::text, is_playoff boolean not null default false, opened_at timestamp with time zone, opened_by uuid, finalized_at timestamp with time zone, finalized_by uuid, finalize_id uuid, created_at timestamp with time zone not null default now(), unique (season_id, week_number));
alter table public.league_cards add constraint league_cards_matchup_slot_uq unique (matchup_id, slot);
alter table public.league_cards add constraint league_cards_source_check check (source = any (array['live_round','solo_post','sub','partner_twice','blind_draw','ghost','course','forfeit']));
alter table public.league_matchups add constraint league_matchups_status_check check (status = any (array['scheduled','live','pending_approval','final','disputed','adjusted','forfeit','void']));
alter table public.league_matchups add constraint league_matchups_kind_check check (kind = any (array['match','bye','vs_field','vs_course']));
-- stubs for functions outside the scoring area that the scoring functions call (never their live bodies)
create or replace function public.league_sync_pool_winners(p_week_id uuid) returns jsonb language sql as $f$ select '{}'::jsonb $f$;
create or replace function public.league_money_recompute(p_season_id uuid) returns jsonb language sql as $f$ select '{"lines":0}'::jsonb $f$;
create or replace function public.league_sweep_expired(p_season_id uuid default null) returns jsonb language sql as $f$ select '{"swept":0}'::jsonb $f$;
